List<string> Doublons(List<string> emails) {
    var vus = new List<string>();
    var doublons = new List<string>();
    foreach (var e in emails) {
        if (vus.Contains(e)) doublons.Add(e);
        else vus.Add(e);
    }
    return doublons;
}

